<?php declare(strict_types=1); use FastWebsite\Core\View; require __DIR__ . '/show.php'; ?>
<section class="admin-panel metadata-panel" id="metadata">
    <div class="panel-heading"><div><p class="eyebrow">Discovery and impact</p><h2>Themes, SDGs, and partners</h2></div><a class="button button-secondary button-compact" href="<?=View::escape($baseUrl)?>admin/research/metadata">Manage catalogues</a></div>
    <div class="metadata-admin-grid">
        <div><h3>Research themes</h3><?php if ($themes === []): ?><p class="admin-empty compact">No themes assigned.</p><?php else: ?><div class="metadata-chip-grid"><?php foreach ($themes as $theme): ?><span class="metadata-chip"><?=View::escape($theme['name'])?><?=$theme['is_primary']?' · Primary':''?><?php if ($canManageMetadata): ?><form method="post" action="<?=View::escape($baseUrl)?>admin/research/projects/<?=(int)$project['id']?>/themes/<?=(int)$theme['id']?>/remove"><input type="hidden" name="_token" value="<?=View::escape($csrfToken)?>"><button type="submit" aria-label="Remove <?=View::escape($theme['name'])?>">×</button></form><?php endif; ?></span><?php endforeach; ?></div><?php endif; ?><?php if ($canManageMetadata && $themeOptions !== []): ?><form class="compact-assignment-form" method="post" action="<?=View::escape($baseUrl)?>admin/research/projects/<?=(int)$project['id']?>/themes"><input type="hidden" name="_token" value="<?=View::escape($csrfToken)?>"><select name="theme_id" required><option value="">Choose published theme</option><?php foreach ($themeOptions as $theme): ?><option value="<?=(int)$theme['id']?>"><?=View::escape($theme['name'])?></option><?php endforeach; ?></select><label><input type="checkbox" name="is_primary" value="1"> Primary</label><button class="button button-primary button-compact" type="submit">Assign</button></form><?php endif; ?></div>
        <div><h3>Sustainable Development Goals</h3><?php if ($sdgLinks === []): ?><p class="admin-empty compact">No SDGs assigned.</p><?php else: ?><div class="metadata-chip-grid"><?php foreach ($sdgLinks as $sdg): ?><span class="metadata-chip sdg-chip" style="--chip-colour:<?=View::escape($sdg['colour_code'] ?: '#425466')?>"><strong><?=View::escape($sdg['code'])?></strong> <?=View::escape($sdg['name'])?><?=$sdg['is_primary']?' · Primary':''?><?php if ($canManageMetadata): ?><form method="post" action="<?=View::escape($baseUrl)?>admin/research/projects/<?=(int)$project['id']?>/sdgs/<?=(int)$sdg['id']?>/remove"><input type="hidden" name="_token" value="<?=View::escape($csrfToken)?>"><button type="submit" aria-label="Remove <?=View::escape($sdg['code'])?>">×</button></form><?php endif; ?></span><?php endforeach; ?></div><?php endif; ?><?php if ($canManageMetadata): ?><form class="compact-assignment-form" method="post" action="<?=View::escape($baseUrl)?>admin/research/projects/<?=(int)$project['id']?>/sdgs"><input type="hidden" name="_token" value="<?=View::escape($csrfToken)?>"><select name="sdg_id" required><option value="">Choose SDG</option><?php foreach ($sdgs as $sdg): ?><option value="<?=(int)$sdg['id']?>"><?=View::escape($sdg['code'].' · '.$sdg['name'])?></option><?php endforeach; ?></select><label><input type="checkbox" name="is_primary" value="1"> Primary</label><button class="button button-primary button-compact" type="submit">Assign</button></form><?php endif; ?></div>
    </div>
    <div class="metadata-partners"><h3>Project partners</h3><?php if ($partnerLinks === []): ?><p class="admin-empty compact">No partner organizations assigned.</p><?php else: ?><div class="table-scroll"><table class="admin-table"><thead><tr><th>Organization</th><th>Role</th><th>Contribution</th><th></th></tr></thead><tbody><?php foreach ($partnerLinks as $partner): ?><tr><th><?=View::escape($partner['name'])?></th><td><?=View::escape(ucwords(str_replace('_', ' ', $partner['partner_role'])))?></td><td><?=View::escape($partner['contribution'] ?? 'Not described')?></td><td><?php if ($canManageMetadata): ?><form method="post" action="<?=View::escape($baseUrl)?>admin/research/projects/<?=(int)$project['id']?>/partners/<?=(int)$partner['link_id']?>/remove"><input type="hidden" name="_token" value="<?=View::escape($csrfToken)?>"><button class="button button-secondary button-compact" type="submit">Remove</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?><?php if ($canManageMetadata && $partnerOptions !== []): ?><form class="content-form member-form compact-metadata-form" method="post" action="<?=View::escape($baseUrl)?>admin/research/projects/<?=(int)$project['id']?>/partners"><input type="hidden" name="_token" value="<?=View::escape($csrfToken)?>"><div class="form-grid"><div class="form-field"><label for="partner_id">Published partner</label><select id="partner_id" name="partner_id" required><option value="">Choose organization</option><?php foreach ($partnerOptions as $partner): ?><option value="<?=(int)$partner['id']?>"><?=View::escape($partner['name'])?></option><?php endforeach; ?></select></div><div class="form-field"><label for="partner_role">Role</label><select id="partner_role" name="partner_role"><?php foreach (['lead','funder','implementer','technical_partner','academic_partner','industry_partner','community_partner','other'] as $role): ?><option value="<?=$role?>"><?=ucwords(str_replace('_', ' ', $role))?></option><?php endforeach; ?></select></div><div class="form-field span-2"><label for="contribution">Contribution</label><textarea id="contribution" name="contribution" rows="3"></textarea></div></div><button class="button button-primary button-compact" type="submit">Assign partner</button></form><?php elseif ($canManageMetadata): ?><p class="field-guidance">Publish a partner in the metadata catalogue before assigning it.</p><?php endif; ?></div>
</section>
